"""Deterministically extend the accepted paintings pilot to its reviewable 20-item bank."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("--write", action="store_true")
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
R = Path(__file__).parent
candidate = json.loads((R / "paintings-pilot10.candidate.json").read_text(encoding="utf-8"))
key = json.loads((R / "paintings-pilot10.key.json").read_text(encoding="utf-8"))
candidate.update(id="prep-wave20-paintings", title="Картины: детали и контекст", description="Двадцать вопросов о знаменитых полотнах, их датах, техниках и зрительских подсказках.")
extra = [
("011","Какая техника указана MoMA для «Постоянства памяти» Дали?",["Масло на холсте","Фреска","Темпера на дереве","Акварель"],0,"MoMA указывает масло на холсте для «Постоянства памяти» Сальвадора Дали. Мягкие часы создают сюрреалистический образ, но техника этого произведения остаётся традиционной живописной.","https://www.moma.org/collection/works/79018","MoMA: масло на холсте.",["Фреску пишут по штукатурке, а не холсту.","Темпера на дереве — другая техника и основа.","Акварель не указана для этого произведения."]),
("012","Как Mauritshuis называет жанр «Девушки с жемчужной серёжкой»?",["Трони","Парадный портрет","Автопортрет","Историческое полотно"],0,"Mauritshuis называет работу тронье: это образ воображаемого типа, а не портрет конкретной модели. Экзотический тюрбан и крупная серьга помогают создать этот характер.","https://www.mauritshuis.nl/en/our-collection/artworks/670-girl-with-a-pearl-earring","Mauritshuis: not a portrait, but a tronie.",["Парадный портрет предполагает заказного персонажа.","Автопортрет изображает художника.","Историческое полотно рассказывает событие."]),
("013","Какой вид искусства представляет «Большая волна» Хокусая в Met?",["Ксилография","Мозаика","Пастель","Фреска"],0,"Met определяет «Большую волну» как цветную ксилографию: печать краской с деревянных досок на бумаге. Поэтому это не уникальная масляная картина.","https://www.metmuseum.org/art/collection/search/45434","Met: woodblock print; ink and color on paper.",["Мозаика собирается из твёрдых кусочков.","Пастель рисуют сухим материалом.","Фреска связана со стеной."]),
("014","Что, согласно Louvre, изображает «Свобода, ведущая народ»?",["Июльское восстание 1830 года","Революцию 1789 года","Парижскую коммуну","Наполеоновские войны"],0,"Louvre уточняет, что полотно относится к трёхдневному Июльскому восстанию 1830 года, а не к революции 1789 года. Аллегория Свободы ведёт людей через баррикаду.","https://www.louvre.fr/en/explore/visitor-trails/the-louvre-s-masterpieces/romanticism-topicality-sensuality","Louvre: three-day uprising of July 1830.",["1789 год — частая, но неверная ассоциация.","Коммуна произошла позднее.","Наполеон не сюжет картины."]),
("015","Какой образ находится в центре композиции «Крика» Мунка?",["Фигура с руками у головы","Фигура с раскрытым зонтом","Фигура с поднятым мечом","Фигура с музыкальным инструментом"],0,"Центральная фигура «Крика» держит руки у головы и раскрывает рот. Музей Мунка рассматривает этот образ как выражение тревоги; мотив существует в нескольких авторских версиях.","https://www.munch.no/en/The-Scream/","Официальный материал MUNCH описывает мотив и несколько его версий.",["Зонта у центральной фигуры нет.","Меч превратил бы сцену в другой сюжет.","Музыкального инструмента фигура не держит."]),
("016","Какие металлы использовал Климт в «Поцелуе», по Belvedere?",["Золото, серебро и платину","Железо и медь","Свинец и олово","Только уголь"],0,"Belvedere отмечает золото, серебро и платину в «Поцелуе». Металлическое сияние объясняет декоративный эффект полотна, но не превращает его в ювелирное изделие.","https://sammlung.belvedere.at/objects/6678/der-kuss-liebespaar","Belvedere collection record lists gold, silver and platinum.",["Железо и медь не названы музеем.","Свинец и олово не относятся к записи.","Уголь не объясняет блеск."]),
("017","Что является главным мотивом «Ложного зеркала» Магритта?",["Огромный глаз","Паровоз","Яблоко","Трубка"],0,"MoMA описывает «Ложное зеркало» Магритта как увеличенный глаз, в радужке которого видны облака. Работа играет с тем, как зритель видит изображение.","https://www.moma.org/collection/works/78938","MoMA collection record: The False Mirror.",["Паровоз связан с другой картиной Магритта.","Яблоко — другой узнаваемый мотив.","Трубка относится к иной работе."]),
("018","Какую технику применил Сёра в «Воскресенье на Гранд-Жатт»?",["Пуантилизм","Гризайль","Сфумато","Импасто"],0,"Сёра помещал рядом небольшие точки чистого цвета, которые оптически соединяются в глазах зрителя. Пуантилизм отличается от предварительного смешивания красок на палитре и сплошных мазков.","https://archive.artic.edu/seurat/seurat_themes.html","Art Institute объясняет оптическое смешение раздельных цветов.",["Сфумато создаёт мягкие переходы, а не раздельные точки.","Гризайль использует ограниченную монохромную палитру.","Импасто означает рельефные слои краски, а не этот принцип цвета."]),
("019","В каком городе Моне написал «Впечатление. Восход солнца»?",["Гавр","Руан","Онфлёр","Марсель"],0,"Моне написал вид внешней гавани Гавра из окна гостиницы ранним утром. Музей Мармоттан связывает название с впечатлением от света, а не подробной топографической зарисовкой.","https://www.marmottan.fr/en/notice/4014/","Индивидуальная карточка музея: окно гостиницы, внешняя гавань Гавра и утренний свет.",["Руан связан с серией соборов, а не этим видом гавани.","Онфлёр — другой нормандский порт.","Марсель не указан местом создания картины."]),
("020","Какую геометрическую форму выделяет «Композиция с красным, синим и жёлтым» Мондриана?",["Прямоугольники","Спирали","Овалы","Треугольники"],0,"Мондриан строит композицию из прямоугольных цветовых полей и чёрных линий. Такая сетка отличается от иллюзорного пейзажа и не изображает предметы природы.","https://www.moma.org/collection/works/80160","MoMA collection record for Mondrian composition.",["Спирали не образуют сетку.","Овалы не являются основой композиции.","Треугольники не доминируют."])]
targets = [0,1,2,3,0,1,3,2,0,1]
for (n,text,options,answer,explanation,source,evidence,distractors), target in zip(extra, targets):
    options = list(options)
    options[answer], options[target] = options[target], options[answer]
    answer = target
    qid=f"wave20-paintings-{n}"; candidate["questions"].append({"id":qid,"type":"choice","text":text,"options":options}); key["records"].append({"id":qid,"correct_answer":answer,"accessed":"2026-10-03","explanation":explanation,"difficulty":"средний","source":source,"evidence":evidence,"distractors":distractors})
records={x["id"]:x for x in key["records"]}; legacy={**candidate,"questions":[{**q,"correct_answer":records[q["id"]]["correct_answer"],"explanation":records[q["id"]]["explanation"]} for q in candidate["questions"]]}
outputs={"paintings20.candidate.json":candidate,"paintings20.key.json":key,"paintings20.legacy.json":legacy}
if args.write:
    for name,obj in outputs.items():
        (R/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
elif args.check:
    assert all(json.loads((R/name).read_text(encoding="utf-8")) == obj for name,obj in outputs.items())
    print("OK: readonly candidate/key/legacy parity")
